      const id = feature.attributes[metadata.oid];
      if (records.has(id)) fail('ARCGIS_DUPLICATE_FEATURE');
      records.set(id, feature);
    }
    sourceBytes += file.bytes; pageHashes.push(file.sha256);
    if (sourceBytes > state.settings.maxSourceBytes || records.size > state.settings.maxRows) fail('ARCGIS_CAPTURE_TOO_LARGE');
  }
  if (state.geometryJoin) {
    const joined = await attachGeometry(directory, state, metadata, records);
    sourceBytes += joined.sourceBytes; spatialReference = joined.spatialReference; pageHashes.push(...joined.pageHashes);
  }
  if (sourceBytes !== state.sourceBytes || identity(spatialReference) !== identity(state.spatialReference) ||
      identity([...records.keys()].sort((a,b) => a-b)) !== identity(state.ids)) fail('ARCGIS_CAPTURE_COVERAGE_MISMATCH');
  return { state, metadata, sha256: record.sha256, records, pageHashes, sourceBytes };
}

// MIT. Create-only portable file products for the original SF30 seller service.
import { mkdir, open, readFile, rm, stat } from 'node:fs/promises';
import { dirname, resolve, join, basename } from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { inspectResponseAsset, prepareResponseAssets, compileAssetRouteOffer,
  responseAssetLimits } from './response-asset.mjs';
import { compileHttpSellerOffer } from './seller.mjs';
import { compileServicePath, orderServiceRoutes } from './route-path.mjs';
import { validateAdmissionTimeout } from './admission.mjs';

const schema = 'stellar-forge.asset-bundle.v1';
const hash = value => createHash('sha256').update(value).digest('hex');
const encoded = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const own = (x, k) => Object.prototype.hasOwnProperty.call(x, k);
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const USAGE = `SF30 file products (no payments or network requests)
  node asset-cli.mjs inspect --file FILE --type MIME [--name DOWNLOAD_NAME]
  node asset-cli.mjs bundle --config SELLER_JSON --out NEW_DIRECTORY
  node asset-cli.mjs verify --directory BUNDLE_DIRECTORY
  node asset-cli.mjs catalog --directory BUNDLE_DIRECTORY --out NEW_JSON_FILE

inspect prints a pinned responseAsset descriptor and the required byte limit.
bundle copies declarative asset-only routes to a private, portable directory.
verify reads every packaged byte and checks config, route and content digests.
catalog exports content-free native offers and pinned product metadata for SF88.
Serve seller.json with the EXISTING serve.mjs; facilitator configuration stays explicit.`;

async function jsonFile(path) {
  const info = await stat(path);
  if (!info.isFile() || info.size > 1024 * 1024) throw new TypeError('Expected a JSON file no larger than 1 MiB');
  const bytes = await readFile(path);
  if (bytes.length > 1024 * 1024) throw new TypeError('JSON file exceeds 1 MiB');
  return { bytes, value: JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)) };
}

function portableConfig(input, configDir) {
  if (!object(input) || input.schema !== 'stellar-forge.seller-service.v1' ||
      !Array.isArray(input.routes) || input.routes.length < 1 || input.routes.length > 64)
    throw new TypeError('Expected seller-service.v1 with 1–64 declarative asset routes');
  responseAssetLimits(input);
  validateAdmissionTimeout(input.admissionTimeoutMs ?? 2000);
  const config = structuredClone(input), ids = new Set(), bindings = new Set(), compiledPaths = [];
  let origin = 'http://127.0.0.1:8423';
  if (config.publicOrigin !== undefined) {
    const url = new URL(config.publicOrigin);
    if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash ||
        url.pathname !== '/' || url.origin !== config.publicOrigin.replace(/\/$/, ''))
      throw new TypeError('publicOrigin must be a canonical HTTPS origin');
    origin = url.origin;
  }
  for (const route of config.routes) {
    if (!object(route) || !/^[A-Za-z0-9_-]{1,64}$/.test(route.id ?? '') || ids.has(route.id) ||
        !object(route.definition) || own(route.definition, 'url') ||
        !own(route, 'responseAsset') || ['response', 'responseFile', 'handler', 'admit', 'offer'].some(key => own(route, key)) ||
        (own(route, 'validateInput') && route.validateInput !== false) || typeof route.path !== 'string' || !/^\/[A-Za-z0-9_.~/-]*$/.test(route.path) ||
        route.path.startsWith('/_seller/') || route.path.includes('//') ||
        new URL(route.path, origin).pathname !== route.path)
      throw new TypeError('Bundle needs unique fixed-path asset definitions without handler/admission modules');
    const offer = compileAssetRouteOffer(route, origin, compileHttpSellerOffer, !config.publicOrigin);
    const binding = offer.extensions.bazaar.info.input.method + ' ' + route.path;
    if (bindings.has(binding)) throw new TypeError('Duplicate method/path in bundle');
    bindings.add(binding); ids.add(route.id);
    compiledPaths.push({ method: offer.extensions.bazaar.info.input.method, path: route.path,
      binding: compileServicePath(offer) });
    route.responseAsset.file = resolve(configDir, route.responseAsset.file);
  }
  orderServiceRoutes(compiledPaths); // Preserve the ORIGINAL native route ambiguity rules.
  return config;
}

async function durableFile(path, bytes) {
  const file = await open(path, 'wx', 0o600);
  try { await file.writeFile(bytes); await file.sync(); }
  finally { await file.close(); }
}

/** No overwrites: one mkdir reserves the exact output name for this invocation.
 * All input files are validated before reserving it. A failed own write cleans up
 * only the directory this invocation created; a peer's existing output is intact. */
export async function createAssetBundle(input, { configDir = process.cwd(), out } = {}) {
  if (typeof out !== 'string' || !out.trim()) throw new TypeError('New output directory required');
  const config = portableConfig(input, configDir);
  const prepared = await prepareResponseAssets(config);
  const directory = resolve(out);
  const output = structuredClone(config), manifest = { schema, config: 'seller.json',
    configSha256: '', assets: [], totalRouteBytes: prepared.retainedBytes };
  const unique = new Map();
  for (const route of output.routes) {
    const snapshot = prepared.assets.get(route.id), metadata = snapshot.metadata;
    const path = `assets/${metadata.sha256}.blob`;
    route.responseAsset.file = path;
    manifest.assets.push({ routeId: route.id, file: path, ...metadata });
    if (!unique.has(metadata.sha256)) unique.set(metadata.sha256, snapshot);
  }
  const configBytes = encoded(output);
  if (configBytes.length > 1024 * 1024) throw new RangeError('Portable seller config exceeds 1 MiB');
  manifest.configSha256 = hash(configBytes);
  // mkdir is exclusive. Never pre-check then rename over somebody else's path.
  await mkdir(directory, { mode: 0o700 });
  try {
    await mkdir(join(directory, 'assets'), { mode: 0o700 });
    for (const [sha, snapshot] of unique) await durableFile(join(directory, 'assets', sha + '.blob'), snapshot.copyBytes());
    await durableFile(join(directory, 'seller.json'), configBytes);
    // Last write is the completion record; interrupted bundles fail verify.
    await durableFile(join(directory, 'manifest.json'), encoded(manifest));
  } catch (error) {
    await rm(directory, { recursive: true, force: true });
    throw error;
  }
  return { directory, manifest, uniqueFiles: unique.size };
}

async function verifiedAssetBundle(directory) {
  const dir = resolve(directory);
  const { value: manifest } = await jsonFile(join(dir, 'manifest.json'));
  if (!object(manifest) || manifest.schema !== schema || manifest.config !== 'seller.json' ||
      !/^[a-f0-9]{64}$/.test(manifest.configSha256 ?? '') || !Array.isArray(manifest.assets))
    throw new TypeError('Invalid asset bundle manifest');
  const { value: input, bytes } = await jsonFile(join(dir, 'seller.json'));
  if (hash(bytes) !== manifest.configSha256) throw new Error('Packaged seller config digest mismatch');
  if (!Array.isArray(input.routes) || input.routes.some(route =>
      !/^assets\/[a-f0-9]{64}\.blob$/.test(route?.responseAsset?.file ?? '') ||
      route.responseAsset.file !== `assets/${route.responseAsset.sha256}.blob`))
    throw new Error('Packaged asset path must be content-addressed inside assets/');
  const config = portableConfig(input, dir);
  const prepared = await prepareResponseAssets(config);
  if (manifest.assets.length !== prepared.assets.size || manifest.totalRouteBytes !== prepared.retainedBytes)
    throw new Error('Bundle manifest route count or size mismatch');
  const seen = new Set();
  for (const entry of manifest.assets) {
    const snapshot = prepared.assets.get(entry?.routeId);
    if (!snapshot || seen.has(entry.routeId) || entry.file !== `assets/${snapshot.metadata.sha256}.blob` ||
        Object.entries(snapshot.metadata).some(([key, value]) => entry[key] !== value))
      throw new Error('Bundle manifest does not match the packaged route');
    seen.add(entry.routeId);
  }
  return { config, prepared, verification:{ verified: true, directory: dir, routes: seen.size,
    totalRouteBytes: prepared.retainedBytes, configSha256: manifest.configSha256 } };
}

export async function verifyAssetBundle(directory) {
  return (await verifiedAssetBundle(directory)).verification;
}

/** Public catalog data only: never copy asset bytes, operator configuration,
 * source paths or manifest config hashes into a buyer-facing listing. */
export async function exportAssetCatalog(directory, out) {
  if (typeof out !== 'string' || !out.trim()) throw new TypeError('New catalog output path required');
  // Use the same validated config and immutable snapshots as verification;
  // no second read, re-hash or retained copy of the merchant's file collection.
  const {config, prepared} = await verifiedAssetBundle(directory);
  if (!config.publicOrigin) throw new TypeError('Catalog export requires the real public HTTPS origin');
  const origin = new URL(config.publicOrigin).origin;
  const resources = config.routes.filter(route => route.definition.method.toUpperCase() === 'GET').map(route => {
    const offer = compileAssetRouteOffer(route, origin, compileHttpSellerOffer);
    const metadata = prepared.assets.get(route.id).metadata;
    return {...offer, type:'http', extensions:{...offer.extensions,
      'stellar-forge-asset':{schema:'stellar-forge.asset-product.v1', ...metadata}}};
  });
  if (!resources.length) throw new TypeError('A downloadable product catalog requires at least one GET route');
  const catalog = {resources};
  const output = encoded(catalog);
  if (output.length > 1024 * 1024) throw new RangeError('Catalog exceeds the original buyer discovery limit');
  const destination = resolve(out);
  // durableFile uses wx. Never delete or replace a pre-existing operator file.
  let created = false, file;
  try {
    file = await open(destination, 'wx', 0o600); created = true;
    await file.writeFile(output); await file.sync();
  } catch (error) {
    if (file) { await file.close().catch(() => {}); file = null; }
    if (created) await rm(destination, {force:true}).catch(() => {});
    throw error;
  } finally { if (file) await file.close(); }
  return {catalogPath:destination, resources:resources.length,
    catalogSha256:hash(output), contentIncluded:false};
}

export async function main(args = process.argv.slice(2)) {
  if (args.length === 1 && args[0] === '--help') { console.log(USAGE); return; }
  const [command, ...rest] = args;
  const allowed = { inspect: ['--file', '--type', '--name'], bundle: ['--config', '--out'], verify: ['--directory'], catalog: ['--directory','--out'] }[command];
  if (!allowed) throw new TypeError(USAGE);
  const options = new Map();
  for (let i = 0; i < rest.length; i += 2) {
    if (!allowed.includes(rest[i]) || options.has(rest[i]) || !rest[i + 1] || rest[i + 1].startsWith('--'))
      throw new TypeError(USAGE);
    options.set(rest[i], rest[i + 1]);
  }
  let result;
  if (command === 'inspect') {
    if (!options.has('--file') || !options.has('--type')) throw new TypeError(USAGE);
    const file = resolve(options.get('--file'));
    const info = await inspectResponseAsset(file, options.get('--type'), options.get('--name') ?? basename(file));
    const { bytes, ...responseAsset } = info;
    result = { responseAsset, bytes, recommendedMaxResponseBytes: Math.max(1024 * 1024, bytes) };
  } else if (command === 'bundle') {
    if (!options.has('--config') || !options.has('--out')) throw new TypeError(USAGE);
    const path = resolve(options.get('--config'));
    result = await createAssetBundle((await jsonFile(path)).value,
      { configDir: dirname(path), out: options.get('--out') });
  } else if (command === 'catalog') {
    if (!options.has('--directory') || !options.has('--out')) throw new TypeError(USAGE);
    result = await exportAssetCatalog(options.get('--directory'), options.get('--out'));
  } else {
    if (!options.has('--directory')) throw new TypeError(USAGE);
    result = await verifyAssetBundle(options.get('--directory'));
  }
  console.log(JSON.stringify(result, null, 2));
  return result;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  main().catch(error => { console.error(error.message); process.exitCode = 1; });

#!/usr/bin/env node
// MIT. Operator commands for the running seller's single-writer availability policy.
import { request } from 'node:http';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const MAX_RESPONSE = 1024 * 1024;
const ROUTE_ID = /^[A-Za-z0-9_-]{1,80}$/;
const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
const TOKEN = /^[a-f0-9]{64}$/;
const CODE = /^[A-Z][A-Z0-9_]{0,79}$/;
const OWN = (object, key) => Object.prototype.hasOwnProperty.call(object, key);
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (code, message, exitCode = 2) => { throw Object.assign(new Error(message), { code, exitCode }); };
const safeText = value => String(value ?? '').replace(/[\u0000-\u001f\u007f-\u009f]/g, ' ');

const HELP = `Seller availability

  node availability/cli.mjs status --url http://127.0.0.1:PORT [--json]
  node availability/cli.mjs pause --url-env SELLER_AVAILABILITY_URL \\
    --revision 0 --route ROUTE_ID [--route ANOTHER_ID] [--reason TEXT]
  node availability/cli.mjs resume --url http://127.0.0.1:PORT \\
    --token-env SELLER_AVAILABILITY_TOKEN --revision 1 --route ROUTE_ID

Commands: status, pause, resume
  --url VALUE       Operations base URL or the startup availabilityControlUrl.
  --url-env NAME    Read that URL from one environment variable.
  --token-env NAME  Read the control token when using an operations base URL.
  --revision N     Required for a change; use the revision already reviewed.
  --route ID       Select one route; repeat for up to 100 distinct route IDs.
  --reason TEXT    Optional change note, up to 160 characters.
  --timeout-ms N   Request deadline, 1–30000 ms; default 10000.
  --json           Print structured output.
  --help           Show this help.

Only the running loopback operations service is used. A stale revision returns
the current state and exits 3; the command never retries a change automatically.
`;

function parseArguments(argv) {
  if (!Array.isArray(argv) || argv.some(value => typeof value !== 'string')) fail('AVAILABILITY_CLI_ARGUMENTS', 'Arguments must be strings.');
  if (!argv.length || argv.includes('--help')) return { help: true };
  const [command, ...args] = argv;
  if (!['status', 'pause', 'resume'].includes(command)) fail('AVAILABILITY_CLI_COMMAND', 'Use status, pause or resume.');
  const result = { command, routeIds: [], json: false, timeoutMs: 10000 };
  const seen = new Set();
  const names = new Map([['--url', 'url'], ['--url-env', 'urlEnv'], ['--token-env', 'tokenEnv'],
    ['--revision', 'revision'], ['--reason', 'reason'], ['--timeout-ms', 'timeoutMs']]);
  for (let index = 0; index < args.length; index++) {
    const flag = args[index];
    if (flag === '--json') { if (seen.has(flag)) fail('AVAILABILITY_CLI_ARGUMENTS', 'Duplicate --json.'); seen.add(flag); result.json = true; continue; }
    if (flag !== '--route' && !names.has(flag)) fail('AVAILABILITY_CLI_ARGUMENTS', 'Unknown option; use --help.');
    const value = args[++index];
    if (value === undefined || value.startsWith('--')) fail('AVAILABILITY_CLI_ARGUMENTS', 'An option value is missing.');
    if (flag === '--route') { result.routeIds.push(value); continue; }
    if (seen.has(flag)) fail('AVAILABILITY_CLI_ARGUMENTS', 'An option was supplied more than once.');
    seen.add(flag); result[names.get(flag)] = value;
  }
  if (Boolean(result.url) === Boolean(result.urlEnv)) fail('AVAILABILITY_CLI_URL', 'Supply exactly one of --url or --url-env.');
  for (const name of ['urlEnv', 'tokenEnv']) if (result[name] !== undefined && !ENV_NAME.test(result[name]))
    fail('AVAILABILITY_CLI_ENV', 'Environment variable names must be valid identifiers.');
  if (typeof result.timeoutMs === 'string') {
    if (!/^[1-9][0-9]*$/.test(result.timeoutMs)) fail('AVAILABILITY_CLI_TIMEOUT', 'Use --timeout-ms from 1 through 30000.');
    result.timeoutMs = Number(result.timeoutMs);
  }
  if (!Number.isSafeInteger(result.timeoutMs) || result.timeoutMs < 1 || result.timeoutMs > 30000)
    fail('AVAILABILITY_CLI_TIMEOUT', 'Use --timeout-ms from 1 through 30000.');
  if (result.command === 'status') {
    if (result.routeIds.length || result.revision !== undefined || result.reason !== undefined)
      fail('AVAILABILITY_CLI_ARGUMENTS', 'status accepts no route, revision or change reason.');
  } else {
    if (typeof result.revision !== 'string' || !/^(?:0|[1-9][0-9]*)$/.test(result.revision) || !Number.isSafeInteger(Number(result.revision)))
      fail('AVAILABILITY_CLI_REVISION', 'A change requires --revision from the state you reviewed.');
    result.revision = Number(result.revision);
    if (!result.routeIds.length || result.routeIds.length > 100 || new Set(result.routeIds).size !== result.routeIds.length || result.routeIds.some(id => !ROUTE_ID.test(id)))
      fail('AVAILABILITY_CLI_ROUTES', 'Select 1–100 distinct route IDs with repeated --route options.');
    if (result.reason !== undefined && (result.reason.length > 160 || /[\u0000-\u001f\u007f]/.test(result.reason)))
      fail('AVAILABILITY_CLI_REASON', 'Use a change reason up to 160 characters without control characters.');
  }
  return result;
}

function connection(options, env) {
  const readEnv = name => {
    const value = OWN(env, name) ? env[name] : undefined;
    if (typeof value !== 'string' || !value) fail('AVAILABILITY_CLI_ENV', 'A selected environment variable is missing or empty.');
    return value;
  };
  const value = options.urlEnv ? readEnv(options.urlEnv) : options.url;
  let url;
  try { url = new URL(value); } catch { fail('AVAILABILITY_CLI_URL', 'Use the local operations base URL or startup availabilityControlUrl.'); }
  if (typeof value !== 'string' || value.length > 512 || url.protocol !== 'http:' ||
      !['127.0.0.1', 'localhost'].includes(url.hostname) || !url.port || url.username || url.password ||
      url.search || value.includes('?') || !['/', '/availability'].includes(url.pathname) ||
      ![url.origin, url.href].includes(value) || (value.includes('#') && (!url.hash || url.pathname !== '/availability')))
    fail('AVAILABILITY_CLI_URL', 'Use a canonical HTTP loopback URL with an explicit port and optional /availability control fragment.');
  if (url.hash && !TOKEN.test(url.hash.slice(1))) fail('AVAILABILITY_CLI_TOKEN', 'The availability control fragment must contain the exact startup token.');
  if (url.hash && options.tokenEnv) fail('AVAILABILITY_CLI_TOKEN', 'Use either the startup URL fragment or --token-env.');
  const token = url.hash ? url.hash.slice(1) : options.tokenEnv ? readEnv(options.tokenEnv) : null;
  if (token !== null && !TOKEN.test(token)) fail('AVAILABILITY_CLI_TOKEN', 'The control token must contain exactly 64 lowercase hexadecimal characters.');
  if (options.command !== 'status' && token === null) fail('AVAILABILITY_CLI_TOKEN', 'A change requires the startup control URL or --token-env.');
  return { origin: url.origin, token };
}

function readSnapshot(value) {
  if (!plain(value)) fail('AVAILABILITY_CLI_RESPONSE', 'The operations service returned an invalid availability response.', 1);
  if (value.available === false) return { available: false, controlsEnabled: value.controlsEnabled === true };
  if (value.schema !== 'stellar-forge.seller-availability.v1' || !Number.isSafeInteger(value.revision) || value.revision < 0 ||
      !['ready', 'unavailable'].includes(value.storageState) || !Array.isArray(value.routes) || value.routes.length > 256 ||
      !Array.isArray(value.retiredPauses) || value.retiredPauses.length > 256 || !Array.isArray(value.recentChanges) || value.recentChanges.length > 32)
    fail('AVAILABILITY_CLI_RESPONSE', 'The operations service returned an invalid availability snapshot.', 1);
  return { schema: value.schema, available: true, controlsEnabled: value.controlsEnabled === true,
    revision: value.revision, savedAt: safeText(value.savedAt), storageState: value.storageState,
    serviceOrigin: safeText(value.serviceOrigin), routes: value.routes.map(row => {
      if (!plain(row) || !ROUTE_ID.test(row.id ?? '') || !['selling', 'pausing', 'paused', 'storage_unavailable'].includes(row.state) ||
          ['inFlight', 'admitted', 'rejected'].some(key => !Number.isSafeInteger(row[key]) || row[key] < 0))
        fail('AVAILABILITY_CLI_RESPONSE', 'The operations service returned an invalid route state.', 1);
      return { id: row.id, method: safeText(row.method), path: safeText(row.path), description: safeText(row.description),
        state: row.state, paused: row.paused === true, reason: safeText(row.reason), changedAt: row.changedAt ?? null,
        inFlight: row.inFlight, admitted: row.admitted, rejected: row.rejected };
    }),
    retiredPauses: value.retiredPauses.map(row => {
      if (!plain(row) || !ROUTE_ID.test(row.id ?? '')) fail('AVAILABILITY_CLI_RESPONSE', 'The operations service returned an invalid retired pause.', 1);
      return { id: row.id, reason: safeText(row.reason), changedAt: safeText(row.changedAt) };
    }),
    recentChanges: value.recentChanges.map(row => {
      if (!plain(row) || !Number.isSafeInteger(row.revision) || !['pause', 'resume'].includes(row.action) ||
          !Array.isArray(row.routeIds) || row.routeIds.length > 100 || row.routeIds.some(id => !ROUTE_ID.test(id)))
        fail('AVAILABILITY_CLI_RESPONSE', 'The operations service returned an invalid change record.', 1);
      return { revision: row.revision, at: safeText(row.at), action: row.action, routeIds: [...row.routeIds], reason: safeText(row.reason) };
    }) };
}

function callService(target, path, { method = 'GET', payload, timeoutMs, signal } = {}) {
  return new Promise((resolve, reject) => {
    let settled = false, outgoing, incoming, timer;
    const chunks = []; let bytes = 0;
    const finish = (error, result) => {
      if (settled) return; settled = true; clearTimeout(timer); signal?.removeEventListener('abort', abort);
      if (error) { incoming?.destroy(); outgoing?.destroy(); reject(error); } else resolve(result);
    };
    const problem = (code, message, exitCode = 1) => finish(Object.assign(new Error(message), { code, exitCode }));
    const abort = () => problem('AVAILABILITY_CLI_ABORTED', 'Availability request interrupted.', 130);
    if (signal?.aborted) return abort();
    signal?.addEventListener('abort', abort, { once: true });
    timer = setTimeout(() => problem('AVAILABILITY_CLI_TIMEOUT', 'The operations request exceeded its deadline; inspect status before another change.'), timeoutMs);
    const body = payload === undefined ? null : Buffer.from(JSON.stringify(payload));
    try {
      outgoing = request(new URL(path, target.origin), { method, agent: false, maxHeaderSize: 16384,
        headers: { accept: 'application/json', 'accept-encoding': 'identity', origin: target.origin,
          ...(target.token ? { 'x-merchant-availability-token': target.token } : {}),
          ...(body ? { 'content-type': 'application/json', 'content-length': String(body.length) } : {}) },
        // A localhost URL still connects directly to IPv4 loopback.
        lookup: (_host, options, callback) => options?.all ? callback(null, [{ address: '127.0.0.1', family: 4 }]) : callback(null, '127.0.0.1', 4),
      }, response => {
        incoming = response;
        if (response.statusCode >= 300 && response.statusCode < 400) return problem('AVAILABILITY_CLI_REDIRECT', 'The operations service returned a redirect; use its original local URL.');
        if (String(response.headers['content-type'] ?? '').split(';')[0].trim().toLowerCase() !== 'application/json' ||
            !['', 'identity'].includes(String(response.headers['content-encoding'] ?? '').toLowerCase()))
          return problem('AVAILABILITY_CLI_RESPONSE', 'The operations service must return uncompressed JSON.');
        response.on('data', chunk => {
          if (settled) return; bytes += chunk.length;
          if (bytes > MAX_RESPONSE) return problem('AVAILABILITY_CLI_RESPONSE_SIZE', 'The operations response exceeded 1 MiB.');
          chunks.push(chunk);
        });
        response.once('aborted', () => problem('AVAILABILITY_CLI_RESPONSE', 'The operations response ended early; inspect status before another change.'));
        response.once('error', () => problem('AVAILABILITY_CLI_RESPONSE', 'The operations response failed; inspect status before another change.'));
        response.once('end', () => {
          if (settled) return;
          if (!response.complete) return problem('AVAILABILITY_CLI_RESPONSE', 'The operations response is incomplete.');
          try { finish(null, { status: response.statusCode, data: JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks))) }); }
          catch { problem('AVAILABILITY_CLI_RESPONSE', 'The operations service returned invalid JSON.'); }
